using Clary.Api.Identity;
namespace Clary.Api;
public static class InventoryEndpoints{
 public static void MapInventoryEndpoints(this WebApplication app){
  app.MapGet("/api/inventory/departments",async(HttpContext http,InventoryDepartments repo,CancellationToken ct)=>await repo.ListAsync(CompanyPolicies.Context(http)!,ct)).WithMetadata(new CompanyPermission(CompanyCapability.Read));
  async Task<IResult> SaveDepartment(HttpContext http,InventoryDepartment input,bool update,InventoryDepartments repo,CancellationToken ct){try{return Results.Ok(await repo.SaveAsync(CompanyPolicies.Context(http)!,input.Name,input.Color,update,ct));}catch(ArgumentException e){return Results.BadRequest(new{error=e.Message});}catch(InventoryConflict e){return Results.Conflict(new{error=e.Message});}catch(InventoryMissing){return Results.NotFound(new{error="This department no longer exists."});}}
  app.MapPost("/api/inventory/departments",(HttpContext http,InventoryDepartment input,InventoryDepartments repo,CancellationToken ct)=>SaveDepartment(http,input,false,repo,ct)).WithMetadata(new CompanyPermission(CompanyCapability.Settings));
  app.MapPut("/api/inventory/departments",(HttpContext http,InventoryDepartment input,InventoryDepartments repo,CancellationToken ct)=>SaveDepartment(http,input,true,repo,ct)).WithMetadata(new CompanyPermission(CompanyCapability.Settings));
  app.MapPost("/api/inventory/documentation/ensure",async(HttpContext http,InventoryDocumentation docs,CancellationToken ct)=>{await docs.EnsureAllAsync(CompanyPolicies.Context(http)!,ct);return Results.Ok(new{ready=true});}).WithMetadata(new CompanyPermission(CompanyCapability.Write));
  app.MapGet("/api/inventory/documentation",async(HttpContext http,string? category,InventoryDocumentation docs,CancellationToken ct)=>{try{return Results.Ok(await docs.GetAsync(CompanyPolicies.Context(http)!,ct,category??"Computer"));}catch(ArgumentException e){return Results.BadRequest(new{error=e.Message});}}).WithMetadata(new CompanyPermission(CompanyCapability.Read));
  app.MapPost("/api/inventory/documentation/link",async(HttpContext http,InventoryDocumentLink input,InventoryDocumentation docs,CancellationToken ct)=>{try{return Results.Ok(await docs.LinkAsync(CompanyPolicies.Context(http)!,input.DocumentId,input.CreateNew,ct,input.Category));}catch(ArgumentException e){return Results.BadRequest(new{error=e.Message});}}).WithMetadata(new CompanyPermission(CompanyCapability.Write));
  app.MapGet("/api/inventory/assets",async(HttpContext http,InventoryRepository repo,CancellationToken ct)=>await repo.ListAsync(CompanyPolicies.Context(http)!,ct)).WithMetadata(new CompanyPermission(CompanyCapability.OwnInventory));
  app.MapGet("/api/inventory/assets/{id:guid}",async(HttpContext http,Guid id,InventoryRepository repo,CancellationToken ct)=>await repo.GetAsync(CompanyPolicies.Context(http)!,id,ct) is {} a?Results.Ok(a):Results.NotFound(new{error="This asset no longer exists."})).WithMetadata(new CompanyPermission(CompanyCapability.OwnInventory));
  app.MapGet("/api/inventory/assets/{id:guid}/history",async(HttpContext http,Guid id,string? cursor,int? limit,AuditRepository repo,CancellationToken ct)=>{try{return Results.Ok(await repo.AssetHistoryAsync(CompanyPolicies.Context(http)!,id,cursor,limit??50,ct));}catch(ArgumentException e){return Results.BadRequest(new{error=e.Message});}catch(InventoryMissing e){return Results.NotFound(new{error=e.Message});}}).WithMetadata(new CompanyPermission(CompanyCapability.OwnInventory));
  async Task<IResult> Save(HttpContext http,Guid? id,AssetInput input,InventoryRepository repo,CancellationToken ct){try{return Results.Ok(id.HasValue?await repo.UpdateAsync(CompanyPolicies.Context(http)!,id.Value,input,ct):await repo.CreateAsync(CompanyPolicies.Context(http)!,input,ct));}catch(ArgumentException e){return Results.BadRequest(new{error=e.Message});}catch(InventoryConflict e){return Results.Conflict(new{error=e.Message});}catch(InventoryMissing e){return Results.NotFound(new{error=e.Message});}}
  app.MapPost("/api/inventory/assets",(HttpContext http,AssetInput input,InventoryRepository repo,CancellationToken ct)=>Save(http,null,input,repo,ct)).WithMetadata(new CompanyPermission(CompanyCapability.Write));
  app.MapPut("/api/inventory/assets/{id:guid}",(HttpContext http,Guid id,AssetInput input,InventoryRepository repo,CancellationToken ct)=>Save(http,id,input,repo,ct)).WithMetadata(new CompanyPermission(CompanyCapability.Write));
  app.MapGet("/api/inventory/activity",async(HttpContext http,int? limit,InventoryRepository repo,CancellationToken ct)=>await repo.ActivityAsync(CompanyPolicies.Context(http)!,limit??10,ct)).WithMetadata(new CompanyPermission(CompanyCapability.OwnInventory));
 }
}


